import{_ as l,a0 as d,w as o,s as h,ao as p,I as t,x as a,a1 as i,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const m=JSON.parse('{"title":"為什麼 0.1 + 0.2 = 0.30000000000000004？ | LCTT x X-CMD","titleTemplate":false,"description":"為什麼 0.1 + 0.2 = 0.30000000000000004？ | LCTT (202305) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"為什麼 0.1 + 0.2 = 0.30000000000000004？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"為什麼 0.1 + 0.2 = 0.30000000000000004？ | LCTT (202305) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202305/20230208.3 ⭐️⭐️⭐️ Why does 0.1 + 0.2 = 0.30000000000000004","title":"為什麼 0.1 + 0.2 = 0.30000000000000004？","tag":"202305","desc":""},"relativePath":"202305/20230208.3 ⭐️⭐️⭐️ Why does 0.1 + 0.2 = 0.30000000000000004.md","filePath":"[post].md"}'),c={name:"202305/20230208.3 ⭐️⭐️⭐️ Why does 0.1 + 0.2 = 0.30000000000000004.md"};function g(r,s,k,b,u,f){const e=d("Link");return o(),h("div",null,[s[23]||(s[23]=p(`<h1 id="為什麼-0-1-0-2-0-30000000000000004" tabindex="-1">為什麼 0.1 + 0.2 = 0.30000000000000004？ <a class="header-anchor" href="#為什麼-0-1-0-2-0-30000000000000004" aria-label="Permalink to “為什麼 0.1 + 0.2 = 0.30000000000000004？”">​</a></h1><p>嗨！昨天我試着寫點關於浮點數的東西，我發現自己對這個 64 位浮點數的計算方法很好奇：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; 0.1 + 0.2</span></span>
<span class="line"><span>0.30000000000000004</span></span></code></pre></div><p>我意識到我並沒有完全理解它是如何計算的。我的意思是，我知道浮點計算是不精確的，你不能精確地用二進制表示 <code>0.1</code>，但是：肯定有一個浮點數比 <code>0.30000000000000004</code> 更接近 0.3！那為什麼答案是 <code>0.30000000000000004</code> 呢？</p><p>如果你不想閲讀一大堆計算過程，那麼簡短的答案是： <code>0.1000000000000000055511151231257827021181583404541015625 + 0.200000000000000011102230246251565404236316680908203125</code> 正好位於兩個浮點數之間，即 <code>0.299999999999999988897769753748434595763683319091796875</code> （通常打印為 <code>0.3</code>） 和 <code>0.3000000000000000444089209850062616169452667236328125</code>（通常打印為 <code>0.30000000000000004</code>）。答案是 <code>0.30000000000000004</code>，因為它的尾數是偶數。</p><h4 id="浮點加法是如何計算的" tabindex="-1">浮點加法是如何計算的 <a class="header-anchor" href="#浮點加法是如何計算的" aria-label="Permalink to “浮點加法是如何計算的”">​</a></h4><p>以下是浮點加法的簡要計算原理：</p><ul><li>把它們精確的數字加在一起</li><li>將結果四捨五入到最接近的浮點數</li></ul><p>讓我們用這些規則來計算 0.1 + 0.2。我昨天才剛瞭解浮點加法的計算原理，所以在這篇文章中我可能犯了一些錯誤，但最終我得到了期望的答案。</p><h4 id="第一步-0-1-和-0-2-到底是多少" tabindex="-1">第一步：0.1 和 0.2 到底是多少 <a class="header-anchor" href="#第一步-0-1-和-0-2-到底是多少" aria-label="Permalink to “第一步：0.1 和 0.2 到底是多少”">​</a></h4><p>首先，讓我們用 Python 計算 <code>0.1</code> 和 <code>0.2</code> 的 64 位浮點值。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; f&quot;{0.1:.80f}&quot;</span></span>
<span class="line"><span>&#39;0.10000000000000000555111512312578270211815834045410156250000000000000000000000000&#39;</span></span>
<span class="line"><span>&gt;&gt;&gt; f&quot;{0.2:.80f}&quot;</span></span>
<span class="line"><span>&#39;0.20000000000000001110223024625156540423631668090820312500000000000000000000000000&#39;</span></span></code></pre></div><p>這確實很精確：因為浮點數是二進制的，你也可以使用十進制來精確的表示。但有時你只是需要一大堆數字:)</p><h4 id="第二步-相加" tabindex="-1">第二步：相加 <a class="header-anchor" href="#第二步-相加" aria-label="Permalink to “第二步：相加”">​</a></h4><p>接下來，把它們加起來。我們可以將小數部分作為整數加起來得到確切的答案：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; 1000000000000000055511151231257827021181583404541015625 + 2000000000000000111022302462515654042363166809082031250</span></span>
<span class="line"><span>3000000000000000166533453693773481063544750213623046875</span></span></code></pre></div><p>所以這兩個浮點數的和是 <code>0.3000000000000000166533453693773481063544750213623046875</code>。</p><p>但這並不是最終答案，因為它不是一個 64 位浮點數。</p><h4 id="第三步-查找最接近的浮點數" tabindex="-1">第三步：查找最接近的浮點數 <a class="header-anchor" href="#第三步-查找最接近的浮點數" aria-label="Permalink to “第三步：查找最接近的浮點數”">​</a></h4><p>現在，讓我們看看接近 <code>0.3</code> 的浮點數。下面是最接近 <code>0.3</code> 的浮點數（它通常寫為 <code>0.3</code>，儘管它不是確切值）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; f&quot;{0.3:.80f}&quot;</span></span>
<span class="line"><span>&#39;0.29999999999999998889776975374843459576368331909179687500000000000000000000000000&#39;</span></span></code></pre></div><p>我們可以通過 <code>struct.pack</code> 將 <code>0.3</code> 序列化為 8 字節來計算出它之後的下一個浮點數，加上 1，然後使用 <code>struct.unpack</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; struct.pack(&quot;!d&quot;, 0.3)</span></span>
<span class="line"><span>b&#39;?\\xd3333333&#39;</span></span>
<span class="line"><span># 手動加 1</span></span>
<span class="line"><span>&gt;&gt;&gt; next_float = struct.unpack(&quot;!d&quot;, b&#39;?\\xd3333334&#39;)[0]</span></span>
<span class="line"><span>&gt;&gt;&gt; next_float</span></span>
<span class="line"><span>0.30000000000000004</span></span>
<span class="line"><span>&gt;&gt;&gt; f&quot;{next_float:.80f}&quot;</span></span>
<span class="line"><span>&#39;0.30000000000000004440892098500626161694526672363281250000000000000000000000000000&#39;</span></span></code></pre></div><p>當然，你也可以用 <code>math.nextafter</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; math.nextafter(0.3, math.inf)</span></span>
<span class="line"><span>0.30000000000000004</span></span></code></pre></div><p>所以 <code>0.3</code> 附近的兩個 64 位浮點數是 <code>0.299999999999999988897769753748434595763683319091796875</code> 和 <code>0.3000000000000000444089209850062616169452667236328125</code>。</p><h4 id="第四步-找出哪一個最接近" tabindex="-1">第四步：找出哪一個最接近 <a class="header-anchor" href="#第四步-找出哪一個最接近" aria-label="Permalink to “第四步：找出哪一個最接近”">​</a></h4><p>結果證明 <code>0.3000000000000000166533453693773481063544750213623046875</code> 正好在 <code>0.299999999999999988897769753748434595763683319091796875</code> 和 <code>0.3000000000000000444089209850062616169452667236328125</code> 的中間。</p><p>你可以通過以下計算看到：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; (3000000000000000444089209850062616169452667236328125000 + 2999999999999999888977697537484345957636833190917968750) // 2 == 3000000000000000166533453693773481063544750213623046875</span></span>
<span class="line"><span>True</span></span></code></pre></div><p>所以它們都不是最接近的。</p><h4 id="如何知道四捨五入到哪一個" tabindex="-1">如何知道四捨五入到哪一個？ <a class="header-anchor" href="#如何知道四捨五入到哪一個" aria-label="Permalink to “如何知道四捨五入到哪一個？”">​</a></h4><p>在浮點數的二進制表示中，有一個數字稱為“尾數”。這種情況下（結果正好在兩個連續的浮點數之間），它將四捨五入到偶數尾數的那個。</p><p>在本例中為 <code>0.300000000000000044408920985006261616945266723632812500</code>。</p><p>我們之前就見到了這個數字的尾數：</p><ul><li>0.30000000000000004 是 <code>struct.unpack(&#39;!d&#39;, b&#39;?\\xd3333334&#39;)</code> 的結果</li><li>0.3 是 <code>struct.unpack(&#39;!d&#39;, b&#39;?\\xd3333333&#39;)</code> 的結果</li></ul><p><code>0.30000000000000004</code> 的大端十六進制表示的最後一位數字是 <code>4</code>，它的尾數是偶數（因為尾數在末尾）。</p><h4 id="我們用二進制來算一下" tabindex="-1">我們用二進制來算一下 <a class="header-anchor" href="#我們用二進制來算一下" aria-label="Permalink to “我們用二進制來算一下”">​</a></h4><p>之前我們都是使用十進制來計算的，這樣讀起來更直觀。但是計算機並不會使用十進制，而是用 2 進制，所以我想知道它是如何計算的。</p><p>我不認為本文的二進制計算部分特別清晰，但它寫出來對我很有幫助。有很多數字，讀起來可能很糟糕。</p><h4 id="_64-位浮點數如何計算-指數和尾數" tabindex="-1">64 位浮點數如何計算：指數和尾數 <a class="header-anchor" href="#_64-位浮點數如何計算-指數和尾數" aria-label="Permalink to “64 位浮點數如何計算：指數和尾數”">​</a></h4><p>64 位浮點數由 2 部分整數構成：<strong>指數</strong>和<strong>尾數</strong>，還有 1 比特 <strong>符號位</strong>.</p><p>以下是指數和尾數對應於實際數字的方程：</p><p>$$\\text{sign} \\times 2^\\text{exponent} (1 + \\frac{\\text{significand}}{2^{52}})$$</p><p>例如，如果指數是 <code>1</code>，尾數是 <code>2**51</code>，符號位是正的，那麼就可以得到：</p><p>$$2^{1} (1 + \\frac{2^{51}}{2^{52}})$$</p><p>它等於 <code>2 * (1 + 0.5)</code>，即 3。</p><h4 id="步驟-1-獲取-0-1-和-0-2-的指數和尾數" tabindex="-1">步驟 1：獲取 0.1 和 0.2 的指數和尾數 <a class="header-anchor" href="#步驟-1-獲取-0-1-和-0-2-的指數和尾數" aria-label="Permalink to “步驟 1：獲取 0.1 和 0.2 的指數和尾數”">​</a></h4><p>我用 Python 編寫了一些低效的函數來獲取正浮點數的指數和尾數:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def get_exponent(f):</span></span>
<span class="line"><span>    # 獲取前 52 個字節</span></span>
<span class="line"><span>    bytestring = struct.pack(&#39;!d&#39;, f)</span></span>
<span class="line"><span>    return int.from_bytes(bytestring, byteorder=&#39;big&#39;) &gt;&gt; 52</span></span>
<span class="line"><span></span></span>
<span class="line"><span>def get_significand(f):</span></span>
<span class="line"><span>    # 獲取後 52 個字節</span></span>
<span class="line"><span>    bytestring = struct.pack(&#39;!d&#39;, f)</span></span>
<span class="line"><span>    x = int.from_bytes(bytestring, byteorder=&#39;big&#39;)</span></span>
<span class="line"><span>    exponent = get_exponent(f)</span></span>
<span class="line"><span>    return x ^ (exponent &lt;&lt; 52)</span></span></code></pre></div><p>我忽略了符號位（第一位），因為我們只需要處理 0.1 和 0.2，它們都是正數。</p><p>首先，讓我們獲取 0.1 的指數和尾數。我們需要減去 1023 來得到實際的指數，因為浮點運算就是這麼計算的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; get_exponent(0.1) - 1023</span></span>
<span class="line"><span>-4</span></span>
<span class="line"><span>&gt;&gt;&gt; get_significand(0.1)</span></span>
<span class="line"><span>2702159776422298</span></span></code></pre></div><p>它們根據 <code>2**指數 + 尾數 / 2**(52 - 指數)</code> 這個公式得到 <code>0.1</code>。</p><p>下面是 Python 中的計算:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; 2**-4 + 2702159776422298 / 2**(52 + 4)</span></span>
<span class="line"><span>0.1</span></span></code></pre></div><p>（你可能會擔心這種計算的浮點精度問題，但在本例中，我很確定它沒問題。因為根據定義，這些數字沒有精度問題 -- 從 <code>2**-4</code> 開始的浮點數以 <code>1/2**(52 + 4)</code> 步長遞增。）</p><p><code>0.2</code> 也一樣:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; get_exponent(0.2) - 1023</span></span>
<span class="line"><span>-3</span></span>
<span class="line"><span>&gt;&gt;&gt; get_significand(0.2)</span></span>
<span class="line"><span>2702159776422298</span></span></code></pre></div><p>它們共同工作得到 <code>0.2</code>:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; 2**-3 + 2702159776422298 / 2**(52 + 3)</span></span>
<span class="line"><span>0.2</span></span></code></pre></div><p>（順便説一下，0.1 和 0.2 具有相同的尾數並不是巧合 —— 因為 <code>x</code> 和 <code>2*x</code> 總是有相同的尾數。）</p><h4 id="步驟-2-重新計算-0-1-以獲得更大的指數" tabindex="-1">步驟 2：重新計算 0.1 以獲得更大的指數 <a class="header-anchor" href="#步驟-2-重新計算-0-1-以獲得更大的指數" aria-label="Permalink to “步驟 2：重新計算 0.1 以獲得更大的指數”">​</a></h4><p><code>0.2</code> 的指數比 <code>0.1</code> 大 -- -3 大於 -4。</p><p>所以我們需要重新計算：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>2**-4 + 2702159776422298 / 2**(52 + 4)</span></span></code></pre></div><p>等於 <code>X / (2**52 + 3)</code></p><p>如果我們解出 <code>2**-4 + 2702159776422298 / 2**(52 + 4) = X / (2**52 + 3)</code>，我們能得到：</p><p><code>X = 2**51 + 2702159776422298 /2</code></p><p>在 Python 中，我們很容易得到：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; 2**51 + 2702159776422298 //2</span></span>
<span class="line"><span>3602879701896397</span></span></code></pre></div><h4 id="步驟-3-添加符號位" tabindex="-1">步驟 3：添加符號位 <a class="header-anchor" href="#步驟-3-添加符號位" aria-label="Permalink to “步驟 3：添加符號位”">​</a></h4><p>現在我們試着做加法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>2**-3 + 2702159776422298 / 2**(52 + 3) + 3602879701896397 / 2**(52 + 3)</span></span></code></pre></div><p>我們需要將 <code>2702159776422298</code> 和 <code>3602879701896397</code> 相加：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; 2702159776422298  + 3602879701896397</span></span>
<span class="line"><span>6305039478318695</span></span></code></pre></div><p>棒。但是 <code>6305039478318695</code> 比 <code>2**52-1</code>（尾數的最大值）大，問題來了:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; 6305039478318695 &gt; 2**52</span></span>
<span class="line"><span>True</span></span></code></pre></div><h4 id="第四步-增加指數" tabindex="-1">第四步：增加指數 <a class="header-anchor" href="#第四步-增加指數" aria-label="Permalink to “第四步：增加指數”">​</a></h4><p>目前結果是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>2**-3 + 6305039478318695 / 2**(52 + 3)</span></span></code></pre></div><p>首先，它減去 2**52：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>2**-2 + 1801439850948199 / 2**(52 + 3)</span></span></code></pre></div><p>完美，但最後的 <code>2**(52 + 3)</code> 需要改為 <code>2**(52 + 2)</code>。</p><p>我們需要將 <code>1801439850948199</code> 除以 2。這就是難題的地方 -- <code>1801439850948199</code> 是一個奇數!</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; 1801439850948199  / 2</span></span>
<span class="line"><span>900719925474099.5</span></span></code></pre></div><p>它正好在兩個整數之間，所以我們四捨五入到最接近它的偶數（這是浮點運算規範要求的），所以最終的浮點結果是:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; 2**-2 + 900719925474100 / 2**(52 + 2)</span></span>
<span class="line"><span>0.30000000000000004</span></span></code></pre></div><p>它就是我們預期的結果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; 0.1 + 0.2</span></span>
<span class="line"><span>0.30000000000000004</span></span></code></pre></div><h4 id="在硬件中它可能並不是這樣工作的" tabindex="-1">在硬件中它可能並不是這樣工作的 <a class="header-anchor" href="#在硬件中它可能並不是這樣工作的" aria-label="Permalink to “在硬件中它可能並不是這樣工作的”">​</a></h4><p>在硬件中做浮點數加法，以上操作方式可能並不完全一模一樣（例如，它並不是求解 “X”），我相信有很多有效的技巧，但我認為思想是類似的。</p><h4 id="打印浮點數是非常奇怪的" tabindex="-1">打印浮點數是非常奇怪的 <a class="header-anchor" href="#打印浮點數是非常奇怪的" aria-label="Permalink to “打印浮點數是非常奇怪的”">​</a></h4><p>我們之前説過，浮點數 0.3 不等於 0.3。它實際上是:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; f&quot;{0.3:.80f}&quot;</span></span>
<span class="line"><span>&#39;0.29999999999999998889776975374843459576368331909179687500000000000000000000000000&#39;</span></span></code></pre></div><p>但是當你打印它時，為什麼會顯示 <code>0.3</code>？</p><p>計算機實際上並沒有打印出數字的精確值，而是打印出了<em>最短</em>的十進制數 <code>d</code>，其中 <code>f</code> 是最接近 <code>d</code> 的浮點數。</p>`,97)),t("p",null,[s[2]||(s[2]=a("事實證明，有效做到這一點很不簡單，有很多關於它的學術論文，比如 ",-1)),i(e,{href:"https://legacy.cs.indiana.edu/~dyb/pubs/FP-Printing-PLDI96.pdf"},{default:n(()=>[...s[0]||(s[0]=[a("快速且準確地打印浮點數",-1)])]),_:1}),s[3]||(s[3]=a("、",-1)),i(e,{href:"https://lists.nongnu.org/archive/html/gcl-devel/2012-10/pdfkieTlklRzN.pdf"},{default:n(()=>[...s[1]||(s[1]=[a("如何準確打印浮點數",-1)])]),_:1}),s[4]||(s[4]=a(" 等。",-1))]),s[24]||(s[24]=p('<h4 id="如果計算機打印出浮點數的精確值-會不會更直觀一些" tabindex="-1">如果計算機打印出浮點數的精確值，會不會更直觀一些？ <a class="header-anchor" href="#如果計算機打印出浮點數的精確值-會不會更直觀一些" aria-label="Permalink to “如果計算機打印出浮點數的精確值，會不會更直觀一些？”">​</a></h4><p>四捨五入到一個乾淨的十進制值很好，但在某種程度上，我覺得如果計算機只打印一個浮點數的精確值可能會更直觀 -- 當你得到一個奇怪的結果時，它可能會讓你看起來不那麼驚訝。</p><p>對我來説，<code>0.1000000000000000055511151231257827021181583404541015625 + 0.200000000000000011102230246251565404236316680908203125 = 0.3000000000000000444089209850062616169452667236328125</code> 比 <code>0.1 + 0.2 = 0.30000000000000000004</code> 驚訝少一點。</p><p>這也許是一個壞主意，因為它肯定會佔用大量的屏幕空間。</p><h4 id="php-快速説明" tabindex="-1">PHP 快速説明 <a class="header-anchor" href="#php-快速説明" aria-label="Permalink to “PHP 快速説明”">​</a></h4><p>有人在評論中指出在 PHP 中 <code>&lt;?php echo (0.1 + 0.2 );?&gt;</code> 會輸出 <code>0.3</code>，這是否説明在 PHP 中浮點運算不一樣？</p>',6)),t("p",null,[s[6]||(s[6]=a("非也 —— 我在 ",-1)),i(e,{href:"https://replit.com/languages/php_cli"},{default:n(()=>[...s[5]||(s[5]=[a("這裏",-1)])]),_:1}),s[7]||(s[7]=a(" 運行:",-1))]),s[25]||(s[25]=p('<p><code>&lt;?php echo (0.1 + 0.2 )- 0.3);?&gt;</code>，得到了與 Python 完全相同的答案：5.5511151231258E-17。因此，浮點運算的基本原理是一樣的。</p><p>我認為在 PHP 中 <code>0.1 + 0.2</code> 輸出 <code>0.3</code> 的原因是 PHP 顯示浮點數的算法沒有 Python 精確 —— 即使這個數字不是最接近 0.3 的浮點數，它也會顯示 <code>0.3</code>。</p><h4 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h4><p>我有點懷疑是否有人能耐心完成以上所有些算術，但它寫出來對我很有幫助，所以我還是發表了這篇文章，希望它能有所幫助。</p><p><em>（題圖：MJ/53e9a241-14c6-4dc7-87d0-f9801cd2d7ab）</em></p><hr>',6)),t("p",null,[s[9]||(s[9]=a("via: ",-1)),i(e,{href:"https://jvns.ca/blog/2023/02/08/why-does-0-1-plus-0-2-equal-0-30000000000000004/"},{default:n(()=>[...s[8]||(s[8]=[a("https://jvns.ca/blog/2023/02/08/why-does-0-1-plus-0-2-equal-0-30000000000000004/",-1)])]),_:1})]),t("p",null,[s[14]||(s[14]=a("作者：",-1)),i(e,{href:"https://jvns.ca/"},{default:n(()=>[...s[10]||(s[10]=[a("Julia Evans",-1)])]),_:1}),s[15]||(s[15]=a(" 選題：",-1)),i(e,{href:"https://github.com/lkxed/"},{default:n(()=>[...s[11]||(s[11]=[a("lkxed",-1)])]),_:1}),s[16]||(s[16]=a(" 譯者：",-1)),i(e,{href:"https://github.com/MjSeven"},{default:n(()=>[...s[12]||(s[12]=[a("MjSeven",-1)])]),_:1}),s[17]||(s[17]=a(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:n(()=>[...s[13]||(s[13]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[20]||(s[20]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[18]||(s[18]=[a("LCTT",-1)])]),_:1}),s[21]||(s[21]=a(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:n(()=>[...s[19]||(s[19]=[a("Linux中國",-1)])]),_:1}),s[22]||(s[22]=a(" 榮譽推出",-1))])])}const C=l(c,[["render",g]]);export{m as __pageData,C as default};
